import type { EngineInterface, Register } from 'claude-code'

// モデルは変えず、ターンごとにプロンプトを $.model.classify で分類して effort だけを切り替える。
// effort を変えると会話部分のプロンプトキャッシュは作り直しになるため、
// - 1ターンの中では effort を固定する（判定は最初のリクエストで一度だけ）
// - 前のターンと同じ effort になるときは何も変えない
// ことで切り替え回数を抑える。

type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'
type Mode = 'auto' | 'off' | Effort

type Category = {
  // classify に渡すラベル。小さなモデルがそのまま書き写せる短い英語にする
  label: string
  // undefined はセッション本来の effort のまま
  effort: Effort | undefined
}

const CATEGORIES: readonly Category[] = [
  { label: 'greeting or small talk', effort: 'low' },
  { label: 'translation, summary or proofreading of text', effort: 'low' },
  { label: 'quick question with a short answer', effort: 'low' },
  { label: 'small edit or running a command', effort: 'medium' },
  { label: 'coding task', effort: 'high' },
  { label: 'hard problem needing deep thought', effort: 'xhigh' },
  { label: 'other', effort: undefined },
]
const LABELS = CATEGORIES.map(c => c.label)
const CLASSIFY_TIMEOUT_MS = 5000

type Decision = { label: string; effort: Effort | undefined }

let mode: Mode = 'auto'
let last: Decision = { label: 'other', effort: undefined }
// turnId -> 判定（turn.start で投げ、turn.step で待つ）
const decisions = new Map<string, Promise<Decision>>()

async function classify($: EngineInterface, text: string): Promise<Decision> {
  const prompt =
    'A developer sent this message to a coding agent. Classify what kind of request it is.\n\n' +
    text.slice(0, 4000)
  const label = await $.model.classify(prompt, LABELS)
  const hit = CATEGORIES.find(c => c.label === label)
  return hit ? { label: hit.label, effort: hit.effort } : { label: 'other', effort: undefined }
}

function decide($: EngineInterface, text: string): Promise<Decision> {
  if (mode === 'off') return Promise.resolve({ label: 'off', effort: undefined })
  if (mode !== 'auto') return Promise.resolve({ label: 'pinned', effort: mode })
  // 続きのターン（テキストなし）は直前の判定を引き継ぐ
  if (!text.trim()) return Promise.resolve(last)

  const timeout = new Promise<Decision>(resolve => {
    $.clock.after(CLASSIFY_TIMEOUT_MS, () => resolve({ label: 'timeout', effort: undefined }))
  })
  const judged = classify($, text).catch(() => ({ label: 'error', effort: undefined }) as Decision)
  return Promise.race([judged, timeout])
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'effort-router',
      description: 'Effort router: /effort-router [auto|off|low|medium|high|xhigh|max]',
    })
    return next(e)
  })

  on('command.run', { command: 'effort-router' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === '') return { text: `effort-router: mode=${mode}, last=${last.label} (${last.effort ?? 'default'})` }
    if (!['auto', 'off', 'low', 'medium', 'high', 'xhigh', 'max'].includes(arg)) {
      return { text: 'usage: /effort-router [auto|off|low|medium|high|xhigh|max]' }
    }
    mode = arg as Mode
    $.ui.status(`effort: ${mode}`)
    return { text: `effort-router: mode=${mode}` }
  })

  // 分類はターン開始と同時に投げ、最初のリクエストで待つ
  on('turn.start', async ($, e, next) => {
    const started = await next(e)
    decisions.set(started.turnId, decide($, e.text))
    return started
  })

  on('turn.step', async function* ($, e, next) {
    // サブエージェントと、effort を持たないモデルには触らない
    if (e.agentId !== undefined || e.effort === undefined) return yield* next(e)

    const pending = decisions.get(e.turnId)
    const decision = pending ? await pending : last
    last = decision

    const effort = decision.effort ?? e.effort
    if (e.index === 0) {
      $.ui.status(`effort: ${effort} (${decision.label})`)
      $.ui.log(`effort-router: ${decision.label} -> ${effort}`, { to: 'debug' })
    }
    return yield* next({ ...e, effort })
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    decisions.delete(e.turnId)
    return done
  })
}

